gdjs.HubCode.userFunc0x2ba8db0 = function GDJSInlineCode(runtimeScene) {
"use strict";
// ----------------------------
// GDevelop JS Event: Dual Code Loader (Old + New, FIXED USERNAME & EVENT VARS, NEW MODE 0-5)
// ----------------------------

const WIDTH = 7;
const HEIGHT = 5;
const TOTAL_CELLS = WIDTH * HEIGHT;

// Get input
const input = runtimeScene.getObjects("InputText");
if (input.length === 0) return;

const rawText = input[0].getString();

const codeUsed = rawText.trimEnd();
runtimeScene.getVariables().get("codeused").setString(codeUsed);

// Get objects early
const objects = runtimeScene.getObjects("Object");
const invalidObj = runtimeScene.getObjects("Invalid");

const setInvalid = show => {
  if (invalidObj.length > 0) invalidObj[0].setOpacity(show ? 255 : 0);
};

const resetRooms = () => objects.forEach(o => o.setAnimation(0));

// ----------------------------
// SHIFT SYSTEM (shared)
const SHIFT_CHARS = "123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
const SHIFT_LEN = SHIFT_CHARS.length;

function charToShiftValue(ch) {
  if (ch >= "0" && ch <= "9") return ch.charCodeAt(0) - 48;
  return ch.charCodeAt(0) - 55;
}

function shiftCharBackward(ch, shift) {
  if (ch === "0") return "0";
  const idx = SHIFT_CHARS.indexOf(ch);
  if (idx === -1) return ch;
  return SHIFT_CHARS[(idx - shift + SHIFT_LEN) % SHIFT_LEN];
}

// ----------------------------
// PERMUTATION (shared)
function buildOrder(p) {
  const order = [];
  switch (p) {
    case 0:
      for (let r = 0; r < HEIGHT; r++)
        for (let c = 0; c < WIDTH; c++)
          order.push(r * WIDTH + c);
      break;

    case 1:
      for (let c = 0; c < WIDTH; c++)
        for (let r = 0; r < HEIGHT; r++)
          order.push(r * WIDTH + c);
      break;

    case 2:
      for (let c = WIDTH - 1; c >= 0; c--)
        for (let r = 0; r < HEIGHT; r++)
          order.push(r * WIDTH + c);
      break;

    case 3:
      for (let r = HEIGHT - 1; r >= 0; r--)
        for (let c = WIDTH - 1; c >= 0; c--)
          order.push(r * WIDTH + c);
      break;

    case 4:
    case 5: {
      let t = 0, b = HEIGHT - 1, l = 0, r = WIDTH - 1;
      while (t <= b && l <= r) {
        if (p === 4) {
          for (let c = l; c <= r; c++) order.push(t * WIDTH + c); t++;
          for (let rr = t; rr <= b; rr++) order.push(rr * WIDTH + r); r--;
          if (t <= b) for (let c = r; c >= l; c--) order.push(b * WIDTH + c); b--;
          if (l <= r) for (let rr = b; rr >= t; rr--) order.push(rr * WIDTH + l); l++;
        } else {
          for (let rr = t; rr <= b; rr++) order.push(rr * WIDTH + l); l++;
          for (let c = l; c <= r; c++) order.push(b * WIDTH + c); b--;
          if (l <= r) for (let rr = b; rr >= t; rr--) order.push(rr * WIDTH + r); r--;
          if (t <= b) for (let c = r; c >= l; c--) order.push(t * WIDTH + c); t++;
        }
      }
      break;
    }

    case 6:
      for (let r = 0; r < HEIGHT; r++)
        if (r % 2 === 0)
          for (let c = 0; c < WIDTH; c++) order.push(r * WIDTH + c);
        else
          for (let c = WIDTH - 1; c >= 0; c--) order.push(r * WIDTH + c);
      break;

    case 7:
      for (let c = 0; c < WIDTH; c++)
        if (c % 2 === 0)
          for (let r = 0; r < HEIGHT; r++) order.push(r * WIDTH + c);
        else
          for (let r = HEIGHT - 1; r >= 0; r--) order.push(r * WIDTH + c);
      break;

    case 8: {
      const rows = [2, 3, 1, 4, 0];
      for (let r of rows)
        for (let c = 0; c < WIDTH; c++)
          order.push(r * WIDTH + c);
      break;
    }

    case 9: {
      const rows = [2, 3, 1, 4, 0];
      for (let r of rows)
        for (let c = WIDTH - 1; c >= 0; c--)
          order.push(r * WIDTH + c);
      break;
    }

    default:
      for (let r = 0; r < HEIGHT; r++)
        for (let c = 0; c < WIDTH; c++)
          order.push(r * WIDTH + c);
  }
  return order;
}

// ----------------------------
// Ensure correct object count
if (objects.length !== TOTAL_CELLS) return;

objects.sort((a, b) =>
  a.getVariables().get("ID").getAsNumber() -
  b.getVariables().get("ID").getAsNumber()
);

// ----------------------------
// 🔀 BRANCH
// ----------------------------

const gameVars = runtimeScene.getGame().getVariables();

if (rawText.startsWith("!,")) {

  // ============================
  // 🆕 NEW SYSTEM (FIXED)
  // ============================

  if (rawText.length < 41) {
    setInvalid(true); resetRooms(); return;
  }

  const dataRaw = rawText.slice(2);

  // ONLY uppercase encoded portion
  const header = dataRaw.slice(0, 39).toUpperCase();

  const shiftedCode = header.slice(0, 35);
  const perm = parseInt(header.charAt(35), 10);
  const shiftChar = header.charAt(36);
  const mode1 = parseInt(header.charAt(37), 10);
  const mode2 = parseInt(header.charAt(38), 10);

  // Username stays original case
  const username = dataRaw.slice(39, 55);

  const shiftVal = charToShiftValue(shiftChar);

  if (
    isNaN(perm) || perm < 0 || perm > 9 ||
    isNaN(shiftVal) || shiftVal < 0 || shiftVal > 34 ||
    isNaN(mode1) || mode1 < 0 || mode1 > 5 ||
    isNaN(mode2) || mode2 < 0 || mode2 > 5
  ) {
    setInvalid(true); resetRooms(); return;
  }

  const roomCode = shiftedCode
    .split("")
    .map(ch => shiftCharBackward(ch, shiftVal))
    .join("");

  let c2 = 0, c3 = 0;
  for (let ch of roomCode) {
    if (ch === "2") c2++;
    if (ch === "3") c3++;
  }

  if (c2 !== 1 || c3 !== 1) {
    setInvalid(true); resetRooms(); return;
  }

  const order = buildOrder(perm);

  order.forEach((idx, i) => {
    const ch = roomCode[i];
    const anim = (ch >= "0" && ch <= "9")
      ? ch.charCodeAt(0) - 48
      : ch.charCodeAt(0) - 55;

    objects[idx].setAnimation(anim);
  });

  // Apply username (case preserved)
  const userText = runtimeScene.getObjects("TheirUser");
  if (userText.length > 0) userText[0].setString(username);

  // Set global variables for special code
  gameVars.get("Event").setNumber(1);
  gameVars.get("Mode1").setNumber(mode1);
  gameVars.get("Mode2").setNumber(mode2);

  setInvalid(false);
  console.log("Loaded NEW code:", username, mode1, mode2);

} else {

  // ============================
  // 🧾 ORIGINAL SYSTEM (unchanged)
  // ============================

  if (rawText.length < 37) {
    setInvalid(true); resetRooms(); return;
  }

  const header = rawText.slice(0, 37).toUpperCase();

  const shiftedCode = header.slice(0, 35);
  const perm = parseInt(header.charAt(35), 10);
  const shiftChar = header.charAt(36);
  const shiftVal = charToShiftValue(shiftChar);

  const username = rawText.slice(37, 53);

  if (
    isNaN(perm) || perm < 0 || perm > 9 ||
    isNaN(shiftVal) || shiftVal < 0 || shiftVal > 34
  ) {
    setInvalid(true); resetRooms(); return;
  }

  const roomCode = shiftedCode
    .split("")
    .map(ch => shiftCharBackward(ch, shiftVal))
    .join("");

  let c1=0,c2=0,c3=0,c4=0,over4=0,cost=0;

  const costMap = {
    "5":2,"6":3,"7":2,"8":3,"9":2,
    "A":3,"B":3,"C":2,"D":3,"E":3,"F":3,
    "G":2,"H":2,"I":3,"J":3,"K":3,"L":3,
    "M":3,"N":3,"O":3,"P":4,"Q":9,"R":4,
    "S":3,"T":4,"U":2,"V":5,"W":3,"X":5,
    "Y":5,"Z":2
  };

  for (let ch of roomCode) {
    if (ch === "1") c1++;
    else if (ch === "2") c2++;
    else if (ch === "3") c3++;
    else if (ch === "4") c4++;
    else if (ch in costMap) {
      over4++;
      cost += costMap[ch];
    }
  }

  if (c1!==3 || c2!==1 || c3!==1 || c4!==2 || over4>12 || cost>35) {
    setInvalid(true); resetRooms(); return;
  }

  const order = buildOrder(perm);

  order.forEach((idx, i) => {
    const ch = roomCode[i];
    const anim = (ch >= "0" && ch <= "9")
      ? ch.charCodeAt(0) - 48
      : ch.charCodeAt(0) - 55;

    objects[idx].setAnimation(anim);
  });

  const userText = runtimeScene.getObjects("TheirUser");
  if (userText.length > 0) userText[0].setString(username);

  // Set global variables for old code
  gameVars.get("Event").setNumber(0);
  gameVars.get("Mode1").setNumber(0);
  gameVars.get("Mode2").setNumber(0);

  setInvalid(false);
  console.log("Loaded OLD code:", username);
}
};
