gdjs.HubCode.userFunc0x5289e28 = function GDJSInlineCode(runtimeScene) {
"use strict";
// ----------------------------
// GDevelop JS Event: Generate Encrypted Layout Code + Username
// ----------------------------

var WIDTH = 7;
var HEIGHT = 5;
var TOTAL_CELLS = WIDTH * HEIGHT;

// Get room objects
const objects = runtimeScene.getObjects("Object");
if (objects.length !== TOTAL_CELLS) return;

// Sort objects by ID (0–34)
objects.sort((a, b) =>
  a.getVariables().get("ID").getAsNumber() -
    b.getVariables().get("ID").getAsNumber()
    );

    // Get username (optional, max 16 chars, strip nulls)
    let username = "";
    const userObj = runtimeScene.getObjects("MyUser");
    if (userObj.length > 0) {
      username = userObj[0]
          .getString()
              .replace(/\u0000/g, "")
                  .slice(0, 16);
                  }

                  // Random permutation (0–9)
                  const perm = Math.floor(Math.random() * 10);

                  // NEW: Random shift (0–34 → 0–Y)
                  const shiftVal = Math.floor(Math.random() * 35);

                  // SHIFT CHARACTER SET (no 0)
                  const SHIFT_CHARS = "123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
                  const SHIFT_LEN = SHIFT_CHARS.length;

                  // Shift forward function
                  function shiftCharForward(ch, shift) {
                    if (ch === "0") return "0";

                      const idx = SHIFT_CHARS.indexOf(ch);
                        if (idx === -1) return ch;

                          return SHIFT_CHARS[(idx + shift) % SHIFT_LEN];
                          }

                          // COST MAP for characters > 4
                          const costMap = {
                            "5":2,"6":3,"7":2,"8":3,"9":2,
                              "A":3,"B":3,"C":2,"D":3,"E":3,"F":3,
                                "G":2,"H":2,"I":3,"J":3,"K":3,"L":3,
                                  "M":3,"N":3,"O":3,"P":4,"Q":9,"R":4,
                                    "S":3,"T":4,"U":2,"V":5,"W":3,"X":5,
                                      "Y":5,"Z":2
                                      };

                                      // ----------------------------
                                      // Build permutation order
                                      function buildOrder(p) {
                                        const order = [];

                                          switch (p) {
                                              case 0:
                                                    for (let r=0;r<HEIGHT;r++)
                                                            for (let c=0;c<WIDTH;c++)
                                                                      order.push(r*WIDTH+c);
                                                                            break;

                                                                                case 1:
                                                                                      for (let c=0;c<WIDTH;c++)
                                                                                              for (let r=0;r<HEIGHT;r++)
                                                                                                        order.push(r*WIDTH+c);
                                                                                                              break;

                                                                                                                  case 2:
                                                                                                                        for (let c=WIDTH-1;c>=0;c--)
                                                                                                                                for (let r=0;r<HEIGHT;r++)
                                                                                                                                          order.push(r*WIDTH+c);
                                                                                                                                                break;

                                                                                                                                                    case 3:
                                                                                                                                                          for (let r=HEIGHT-1;r>=0;r--)
                                                                                                                                                                  for (let c=WIDTH-1;c>=0;c--)
                                                                                                                                                                            order.push(r*WIDTH+c);
                                                                                                                                                                                  break;

                                                                                                                                                                                      case 4: case 5: {
                                                                                                                                                                                            let t=0,b=HEIGHT-1,l=0,r=WIDTH-1;
                                                                                                                                                                                                  while (t<=b && l<=r) {
                                                                                                                                                                                                          if (p===4) {
                                                                                                                                                                                                                    for (let c=l;c<=r;c++) order.push(t*WIDTH+c);
                                                                                                                                                                                                                              t++;
                                                                                                                                                                                                                                        for (let rr=t;rr<=b;rr++) order.push(rr*WIDTH+r);
                                                                                                                                                                                                                                                  r--;
                                                                                                                                                                                                                                                            if (t<=b) for (let c=r;c>=l;c--) order.push(b*WIDTH+c);
                                                                                                                                                                                                                                                                      b--;
                                                                                                                                                                                                                                                                                if (l<=r) for (let rr=b;rr>=t;rr--) order.push(rr*WIDTH+l);
                                                                                                                                                                                                                                                                                          l++;
                                                                                                                                                                                                                                                                                                  } else {
                                                                                                                                                                                                                                                                                                            for (let rr=t;rr<=b;rr++) order.push(rr*WIDTH+l);
                                                                                                                                                                                                                                                                                                                      l++;
                                                                                                                                                                                                                                                                                                                                for (let c=l;c<=r;c++) order.push(b*WIDTH+c);
                                                                                                                                                                                                                                                                                                                                          b--;
                                                                                                                                                                                                                                                                                                                                                    if (l<=r) for (let rr=b;rr>=t;rr--) order.push(rr*WIDTH+r);
                                                                                                                                                                                                                                                                                                                                                              r--;
                                                                                                                                                                                                                                                                                                                                                                        if (t<=b) for (let c=r;c>=l;c--) order.push(t*WIDTH+c);
                                                                                                                                                                                                                                                                                                                                                                                  t++;
                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                      break;
                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                              case 6:
                                                                                                                                                                                                                                                                                                                                                                                                                    for (let r=0;r<HEIGHT;r++)
                                                                                                                                                                                                                                                                                                                                                                                                                            if (r%2===0)
                                                                                                                                                                                                                                                                                                                                                                                                                                      for (let c=0;c<WIDTH;c++) order.push(r*WIDTH+c);
                                                                                                                                                                                                                                                                                                                                                                                                                                              else
                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (let c=WIDTH-1;c>=0;c--) order.push(r*WIDTH+c);
                                                                                                                                                                                                                                                                                                                                                                                                                                                              break;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                  case 7:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (let c=0;c<WIDTH;c++)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (c%2===0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          for (let r=0;r<HEIGHT;r++) order.push(r*WIDTH+c);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (let r=HEIGHT-1;r>=0;r--) order.push(r*WIDTH+c);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  break;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      case 8: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const rows=[2,3,1,4,0];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  for (let r of rows)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          for (let c=0;c<WIDTH;c++) order.push(r*WIDTH+c);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        case 9: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const rows=[2,3,1,4,0];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    for (let r of rows)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (let c=WIDTH-1;c>=0;c--) order.push(r*WIDTH+c);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  break;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          default:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for (let r=0;r<HEIGHT;r++)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (let c=0;c<WIDTH;c++)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  order.push(r*WIDTH+c);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return order;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const order = buildOrder(perm);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // ----------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // Convert animations → characters (NULL-SAFE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const layoutChars = order.map(i => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let anim = objects[i].getAnimation();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!Number.isFinite(anim) || anim < 0) anim = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (anim < 10) return String(anim);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if (anim <= 35) return String.fromCharCode(anim + 55);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return "0";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Apply SHIFT ENCRYPTION
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const shiftedLayout = layoutChars
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  .map(ch => shiftCharForward(ch, shiftVal))
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .join("");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ----------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // VALIDATION (use ORIGINAL values, not shifted)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let c1=0,c2=0,c3=0,c4=0,over4=0,cost=0;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    for (let ch of layoutChars) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (ch==="1") c1++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else if (ch==="2") c2++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          else if (ch==="3") c3++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            else if (ch==="4") c4++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              else if (ch in costMap) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  over4++;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      cost+=costMap[ch];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (c1!==3 || c2!==1 || c3!==1 || c4!==2 || over4>12 || cost>35) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          console.log("Invalid layout — code not generated");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Convert shift value → character (0–Y)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const shiftChar = shiftVal < 10
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ? String(shiftVal)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                : String.fromCharCode(shiftVal + 55);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ----------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Final code
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const finalCode = (shiftedLayout + perm + shiftChar + username)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  .replace(/\u0000/g, "");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // Write to DisplayText
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const display = runtimeScene.getObjects("DisplayText");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (display.length > 0) display[0].setString(finalCode);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  console.log("Code generated:", finalCode);
};
