gdjs.HubCode.userFunc0x5978398 = function GDJSInlineCode(runtimeScene) {
"use strict";
// ----------------------------
// Copy DisplayText object string to clipboard
// Works with Chrome, Safari, iPhone/iPad, etc.
// ----------------------------

// Get the DisplayText object
const displayObjects = runtimeScene.getObjects("DisplayText");
if (displayObjects.length === 0) {
  console.log("DisplayText object not found");
  return;
}

// Get the string from the first DisplayText object
const textToCopy = displayObjects[0].getString();


// Try the modern Clipboard API first
if (navigator.clipboard && window.isSecureContext) {

  navigator.clipboard.writeText(textToCopy)
    .then(() => {
      console.log("Copied to clipboard:", textToCopy);
    })
    .catch((err) => {
      console.log("Clipboard API failed, trying fallback:", err);
      fallbackCopy(textToCopy);
    });

} else {

  // Clipboard API unavailable — use fallback
  fallbackCopy(textToCopy);
}


// ----------------------------
// Fallback copy method
// ----------------------------
function fallbackCopy(text) {

  const textArea = document.createElement("textarea");

  textArea.value = text;

  // Prevent the textarea from being visible
  textArea.style.position = "fixed";
  textArea.style.left = "-9999px";
  textArea.style.top = "0";
  textArea.style.opacity = "0";

  document.body.appendChild(textArea);

  // iOS/Safari needs the textarea to be selected
  textArea.focus();
  textArea.select();
  textArea.setSelectionRange(0, textArea.value.length);

  let successful = false;

  try {
    successful = document.execCommand("copy");
  } catch (err) {
    console.error("Fallback copy failed:", err);
  }

  document.body.removeChild(textArea);

  if (successful) {
    console.log("Copied to clipboard:", text);
  } else {
    console.error("Failed to copy text");
  }
}
};
